@import "tailwindcss";

@custom-variant dark (&:is(.dark *));
@custom-variant compact (&:is([data-density="compact"] *));

@source "../../../../apps/**/*.{ts,tsx}";
@source "../**/*.{ts,tsx}";

@theme inline {
  --font-sans: var(--font-ui);
  --font-serif: var(--font-editorial);
  --font-mono: var(--font-numeric);

  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-presence: var(--presence);
  --color-presence-foreground: var(--presence-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-success: var(--success);
  --color-warning: var(--warning);
  --color-information: var(--information);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --color-tool-read: var(--tool-read);
  --color-tool-write: var(--tool-write);
  --color-tool-exec: var(--tool-exec);
  --color-tool-net: var(--tool-net);
  --color-chart-1: var(--chart-1);
  --color-chart-2: var(--chart-2);
  --color-chart-3: var(--chart-3);
  --color-chart-4: var(--chart-4);
  --color-chart-5: var(--chart-5);

  --radius-sm: var(--radius-1);
  --radius-md: var(--radius-2);
  --radius-lg: var(--radius-3);
  --radius-xl: var(--radius-4);
}

:root {
  color-scheme: light;

  /* OpenCoven/brand web profile v1.0.0, pinned to 798e2f5f2f1a69f5d156ccc0a9aafc4f7da55fc8. */
  --oc-bg: #fcfafe;
  --oc-surface-1: #ffffff;
  --oc-surface-2: #f6f0fa;
  --oc-surface-3: #ece3f2;
  --oc-text: #1a1320;
  --oc-text-muted: #5d5265;
  --oc-text-subtle: #74667e;
  --oc-border: #d8cce0;
  --oc-border-strong: #b9a8c4;
  --oc-action: #7a22ee;
  --oc-action-hover: #6410cc;
  --oc-on-action: #ffffff;
  --oc-focus: #6e19da;
  --oc-presence: #5e2a8a;
  --oc-on-presence: #ffffff;
  --oc-success-bg: #e7f6ec;
  --oc-success-text: #17683a;
  --oc-pending-bg: #fff4d3;
  --oc-pending-text: #704b00;
  --oc-blocked-bg: #fdebec;
  --oc-blocked-text: #8a1c1c;
  --oc-evidence-bg: #f2edf5;
  --oc-evidence-text: #4a3f51;
  --oc-font-display: Geist, Inter, "SF Pro Display", system-ui, sans-serif;
  --oc-font-reading: Inter, "SF Pro Text", system-ui, sans-serif;
  --oc-font-mono:
    "SFMono-Regular", ui-monospace, Menlo, Monaco, Consolas, monospace;
  --oc-type--1: clamp(0.875rem, 0.84rem + 0.15vw, 0.95rem);
  --oc-type-0: clamp(1rem, 0.96rem + 0.2vw, 1.125rem);
  --oc-type-1: clamp(1.2rem, 1.08rem + 0.55vw, 1.5rem);
  --oc-type-2: clamp(1.5rem, 1.28rem + 1vw, 2rem);
  --oc-type-3: clamp(2rem, 1.55rem + 2vw, 3rem);
  --oc-type-4: clamp(2.75rem, 1.9rem + 3.8vw, 5rem);
  --oc-leading-reading: 1.62;
  --oc-leading-heading: 1.05;
  --oc-reading-measure: 68ch;
  --oc-technical-measure: 80ch;
  --oc-tracking-heading: -0.035em;
  --oc-tracking-label: 0.12em;
  --oc-space-1: 0.25rem;
  --oc-space-2: 0.5rem;
  --oc-space-3: 0.75rem;
  --oc-space-4: 1rem;
  --oc-space-6: 1.5rem;
  --oc-space-8: 2rem;
  --oc-space-12: 3rem;
  --oc-space-16: 4rem;
  --oc-space-24: 6rem;
  --oc-shadow-1: 0 1px 2px rgb(26 19 32 / 8%);
  --oc-shadow-2: 0 12px 32px rgb(26 19 32 / 12%);

  --background: var(--oc-bg);
  --foreground: var(--oc-text);
  --card: var(--oc-surface-1);
  --card-foreground: var(--oc-text);
  --popover: var(--oc-surface-1);
  --popover-foreground: var(--oc-text);
  --primary: var(--oc-action);
  --primary-foreground: var(--oc-on-action);
  --secondary: var(--oc-surface-2);
  --secondary-foreground: var(--oc-text);
  --muted: var(--oc-surface-2);
  --muted-foreground: var(--oc-text-muted);
  --accent: var(--oc-surface-3);
  --accent-foreground: var(--oc-text);
  --presence: var(--oc-presence);
  --presence-foreground: var(--oc-on-presence);
  --destructive: var(--oc-blocked-text);
  --destructive-foreground: var(--oc-bg);
  --success: var(--oc-success-text);
  --warning: var(--oc-pending-text);
  --information: var(--oc-evidence-text);
  --border: var(--oc-border);
  --input: var(--oc-border);
  --ring: var(--oc-focus);

  --tool-read: #3f6f99;
  --tool-write: #3e7d5c;
  --tool-exec: #8a6a24;
  --tool-net: #b3505e;
  --chart-1: var(--tool-read);
  --chart-2: var(--tool-exec);
  --chart-3: var(--tool-write);
  --chart-4: var(--tool-net);
  --chart-5: var(--presence);

  --font-ui: var(--oc-font-reading);
  --font-display: var(--oc-font-display);
  --font-editorial: var(--oc-font-display);
  --font-numeric: var(--oc-font-mono);

  --density-control: 2rem;
  --density-row: var(--oc-space-3);
  --density-panel: var(--oc-space-6);
  --density-gap: var(--oc-space-4);

  --radius-1: 4px;
  --radius-2: 8px;
  --radius-3: 12px;
  --radius-4: 16px;

  --elevation-1: var(--oc-shadow-1);
  --elevation-2: var(--oc-shadow-2);
  --elevation-3: var(--oc-shadow-2);
  --overlay: rgb(255 255 255 / 96%);

  --motion-fast: 120ms;
  --motion-standard: 180ms;
  --motion-slow: 320ms;
  --motion-ease: cubic-bezier(0.2, 0, 0, 1);
}

.dark {
  color-scheme: dark;
  --oc-bg: #050409;
  --oc-surface-1: #0f0d14;
  --oc-surface-2: #17131e;
  --oc-surface-3: #211a2b;
  --oc-text: #f7f3fa;
  --oc-text-muted: #cbbfd3;
  --oc-text-subtle: #a998b5;
  --oc-border: #3b3146;
  --oc-border-strong: #5b4b69;
  --oc-action: #8e3dff;
  --oc-action-hover: #7a22ee;
  --oc-on-action: #ffffff;
  --oc-focus: #c9a7ff;
  --oc-presence: #b991ff;
  --oc-on-presence: #050409;
  --oc-success-bg: #11281b;
  --oc-success-text: #93e6b4;
  --oc-pending-bg: #2b210d;
  --oc-pending-text: #ffd27a;
  --oc-blocked-bg: #321517;
  --oc-blocked-text: #ffb4ac;
  --oc-evidence-bg: #201a25;
  --oc-evidence-text: #e8e0f0;
  --oc-shadow-1: 0 1px 2px rgb(0 0 0 / 40%);
  --oc-shadow-2: 0 16px 40px rgb(0 0 0 / 42%);

  --tool-read: #7fa5c9;
  --tool-write: #86b39a;
  --tool-exec: #c9a86a;
  --tool-net: #c77882;
  --overlay: rgb(32 32 36 / 96%);
}

[data-density="compact"] {
  --density-control: 1.75rem;
  --density-row: var(--oc-space-2);
  --density-panel: var(--oc-space-4);
  --density-gap: var(--oc-space-2);
}

@layer base {
  * {
    border-color: var(--border);
  }

  html {
    background: var(--background);
  }

  body {
    margin: 0;
    background: var(--background);
    color: var(--foreground);
    font-family: var(--font-ui);
    -webkit-font-smoothing: antialiased;
  }

  button,
  input,
  textarea,
  select {
    font: inherit;
  }

  :focus-visible {
    outline: 2px solid var(--ring);
    outline-offset: 2px;
  }
}

@layer utilities {
  .numeric {
    font-family: var(--font-numeric);
    font-variant-numeric: tabular-nums;
  }

  .editorial {
    font-family: var(--font-editorial);
  }

  .surface {
    border: 1px solid var(--border);
    border-radius: var(--radius-3);
    background: var(--card);
    color: var(--card-foreground);
    box-shadow: var(--elevation-1);
  }
}

@keyframes coven-pulse {
  0%,
  100% {
    opacity: 0.45;
  }
  50% {
    opacity: 1;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

@media (forced-colors: active) {
  :focus-visible {
    outline-color: Highlight;
  }

  [data-slot="tabs-trigger"][data-active],
  [data-slot="mode-switch"] button[aria-pressed="true"] {
    outline: 2px solid Highlight;
    outline-offset: -4px;
  }
}
